import { Component, computed, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ActivatedRoute, RouterLink } from '@angular/router';
import { DataService, Cita, Venta } from '../../services/data.service';

type Item = (Cita | Venta) & { esVenta?: boolean };

@Component({
  selector: 'app-pago',
  standalone: true,
  imports: [CommonModule, RouterLink],
  templateUrl: './pago.component.html',
  styleUrl: './pago.component.css'
})
export class PagoComponent {
  tipo: 'cita' | 'venta';
  id: number;
  metodoSeleccionado = signal<number | null>(null);
  procesando = signal(false);
  resultado = signal<Cita | Venta | null>(null);

  constructor(private route: ActivatedRoute, public data: DataService) {
    this.tipo = this.route.snapshot.paramMap.get('tipo') === 'venta' ? 'venta' : 'cita';
    this.id = Number(this.route.snapshot.paramMap.get('id'));
  }

  item = computed<Item | undefined>(() => {
    if (this.tipo === 'cita') {
      return this.data.citas().find(c => c.id === this.id);
    }
    return this.data.ventas().find(v => v.id === this.id);
  });

  esCita(item: Item): item is Cita {
    return this.tipo === 'cita';
  }

  elegirMetodo(id: number) {
    this.metodoSeleccionado.set(id);
  }

  confirmarPago() {
    const metodoId = this.metodoSeleccionado();
    if (metodoId === null) return;
    this.procesando.set(true);

    if (this.tipo === 'cita') {
      this.data.pagarCita(this.id, metodoId, actualizada => {
        this.procesando.set(false);
        this.resultado.set(actualizada);
      });
    } else {
      this.data.pagarVenta(this.id, metodoId, actualizada => {
        this.procesando.set(false);
        this.resultado.set(actualizada);
      });
    }
  }

  formatPrecio(valor: number): string {
    return '$' + valor.toLocaleString('es-CO');
  }
}
<div class="pago-shell">
  <header class="pago-top">
    <a routerLink="/" class="pago-brand"><span class="pago-mark">K</span> Kutt</a>
  </header>

  <main class="pago-main" *ngIf="item() as it">
    <!-- Antes de pagar: elegir metodo -->
    <section class="pago-card" *ngIf="!resultado()">
      <p class="eyebrow">{{ tipo === 'cita' ? 'Pago de tu cita' : 'Pago de tu compra' }}</p>
      <h1 class="pago-total">{{ formatPrecio(it.total) }}</h1>
      <p class="pago-detalle" *ngIf="tipo === 'venta'">{{ $any(it).detalle }}</p>
      <p class="pago-detalle" *ngIf="tipo === 'cita'">
        {{ $any(it).servicio }}<span *ngIf="$any(it).adicionales"> + {{ $any(it).adicionales }}</span>
      </p>

      <p class="group-label">Elige cómo pagar</p>
      <div class="metodo-list">
        <button class="metodo-option" *ngFor="let m of data.metodosPago()"
                [class.selected]="metodoSeleccionado() === m.id" (click)="elegirMetodo(m.id)">
          <span class="metodo-nombre">{{ m.nombre }}</span>
          <span class="metodo-tipo">{{ m.tipo === 'DIGITAL' ? 'Pago inmediato con QR' : 'Pagas en el local' }}</span>
        </button>
      </div>

      <button class="btn-gold" [disabled]="metodoSeleccionado() === null || procesando()" (click)="confirmarPago()">
        {{ procesando() ? 'Generando...' : 'Continuar' }}
      </button>
    </section>

    <!-- Resultado: QR de pago real -->
    <section class="pago-card resultado" *ngIf="resultado() as r" >
      <ng-container *ngIf="r.tipoQr === 'DIGITAL'; else ticket">
        <div class="check-circle">✓</div>
        <h1>¡Listo, ya pagaste!</h1>
        <p class="pago-detalle">Escaneaste el QR y tu pago de {{ formatPrecio(r.total) }} quedó confirmado con {{ r.metodoPago }}.</p>
        <div class="qr-box"></div>
      </ng-container>
      <ng-template #ticket>
        <div class="ticket-icon">🎫</div>
        <h1>Tu reserva quedó lista</h1>
        <p class="pago-detalle">Vas a pagar {{ formatPrecio(r.total) }} en efectivo. Presenta este ticket QR el día de tu cita para pagar.</p>
        <div class="qr-box"></div>
      </ng-template>

      <a routerLink="/mis-citas" class="btn-outline" style="margin-top:18px; width:auto; display:inline-flex; padding:12px 22px;" *ngIf="tipo === 'cita'">Ver mis citas</a>
      <a routerLink="/productos" class="btn-outline" style="margin-top:18px; width:auto; display:inline-flex; padding:12px 22px;" *ngIf="tipo === 'venta'">Seguir comprando</a>
    </section>
  </main>

  <main class="pago-main" *ngIf="!item()">
    <p class="pago-detalle">No se encontró la {{ tipo === 'cita' ? 'cita' : 'compra' }} indicada.</p>
  </main>
</div>
